<body>
<div class="wrap">
  <header>
    <section class="hero">
      <h1>First-Principles Claim Ladder</h1>
      <p class="sub">Break a big plan into claims, assumptions, evidence, and experiments. Move each card up the ladder as it gets stronger. If the lower rungs are weak, the plan collapses before the fancy conclusion gets to count.</p>
    </section>

    <section class="scorebox" aria-live="polite">
      <div class="scoretop">
        <div>
          <div class="score" id="scoreText">0</div>
          <div class="sub" id="scoreNote">Add or test cards to score the plan.</div>
        </div>
        <div class="verdict" id="verdict">Unbuilt</div>
      </div>
      <div class="meter"><div class="fill" id="scoreFill"></div></div>
      <div class="scoregrid">
        <div class="mini"><b id="foundationCount">0</b><span>foundation cards</span></div>
        <div class="mini"><b id="proofCount">0</b><span>proof cards</span></div>
        <div class="mini"><b id="experimentCount">0</b><span>test cards</span></div>
      </div>
    </section>
  </header>

  <main class="app">
    <section class="panel">
      <h2>Build a card</h2>

      <div class="field">
        <label for="planName">Plan name</label>
        <input id="planName" value="Launch the new offer in 30 days">
      </div>

      <div class="field">
        <label for="cardType">Card type</label>
        <select id="cardType">
          <option value="claim">Claim</option>
          <option value="assumption">Assumption</option>
          <option value="evidence">Evidence</option>
          <option value="experiment">Experiment</option>
        </select>
      </div>

      <div class="field">
        <label for="cardTitle">Card title</label>
        <input id="cardTitle" placeholder="Example: Buyers urgently need this">
      </div>

      <div class="field">
        <label for="cardBody">Reasoning note</label>
        <textarea id="cardBody" placeholder="Write the actual claim, assumption, proof, or test."></textarea>
      </div>

      <div class="fieldrow">
        <div class="field">
          <label for="confidence">Confidence</label>
          <select id="confidence">
            <option value="1">Low</option>
            <option value="2" selected>Medium</option>
            <option value="3">High</option>
          </select>
        </div>
        <div class="field">
          <label for="impact">Impact if wrong</label>
          <select id="impact">
            <option value="1">Small</option>
            <option value="2" selected>Material</option>
            <option value="3">Fatal</option>
          </select>
        </div>
      </div>

      <div class="controls">
        <button id="addCard">Add card</button>
        <button class="ghost" id="loadSample">Load sample</button>
        <button class="danger" id="resetBoard">Reset</button>
      </div>

      <p class="help">Select a card, then use the arrow buttons on the card to move it. Higher rungs score better, but unsupported top claims still get penalized.</p>
    </section>

    <section class="ladder" id="ladder" aria-label="Claim ladder"></section>

    <section class="panel">
      <h2>Collapse checks</h2>
      <div class="warningList" id="warnings"></div>

      <h2 style="margin-top:1rem">Reasoning receipt</h2>
      <div class="receipt" id="receipt" tabindex="0"></div>

      <div class="controls">
        <button id="copyReceipt">Copy receipt</button>
        <button class="ghost" id="downloadReceipt">Download .txt</button>
      </div>
      <div class="status" id="copyStatus"></div>
    </section>
  </main>
</div>

<script>
(function(){
  "use strict";

  var rungs = [
    {id:"raw", name:"1. Raw hunch", note:"Interesting, but not earned yet."},
    {id:"first", name:"2. First-principles break", note:"Reduced into base causes, incentives, constraints, or mechanics."},
    {id:"proof", name:"3. Evidence attached", note:"Supported by observed proof, customer signal, data, or prior result."},
    {id:"test", name:"4. Experiment designed", note:"A cheap test can falsify or strengthen it."},
    {id:"held", name:"5. Holds for now", note:"Strong enough to plan around, but still monitored."}
  ];

  var cards = [];
  var selectedId = null;

  var el = {
    ladder:document.getElementById("ladder"),
    warnings:document.getElementById("warnings"),
    receipt:document.getElementById("receipt"),
    scoreText:document.getElementById("scoreText"),
    scoreNote:document.getElementById("scoreNote"),
    verdict:document.getElementById("verdict"),
    scoreFill:document.getElementById("scoreFill"),
    foundationCount:document.getElementById("foundationCount"),
    proofCount:document.getElementById("proofCount"),
    experimentCount:document.getElementById("experimentCount"),
    planName:document.getElementById("planName"),
    cardType:document.getElementById("cardType"),
    cardTitle:document.getElementById("cardTitle"),
    cardBody:document.getElementById("cardBody"),
    confidence:document.getElementById("confidence"),
    impact:document.getElementById("impact"),
    addCard:document.getElementById("addCard"),
    loadSample:document.getElementById("loadSample"),
    resetBoard:document.getElementById("resetBoard"),
    copyReceipt:document.getElementById("copyReceipt"),
    downloadReceipt:document.getElementById("downloadReceipt"),
    copyStatus:document.getElementById("copyStatus")
  };

  function uid(){
    return "c" + Math.random().toString(16).slice(2) + String(Date.now());
  }

  function typeLabel(type){
    if(type === "claim") return "Claim";
    if(type === "assumption") return "Assumption";
    if(type === "evidence") return "Evidence";
    return "Experiment";
  }

  function rungIndex(card){
    for(var i=0;i<rungs.length;i++){
      if(rungs[i].id === card.rung) return i;
    }
    return 0;
  }

  function makeCard(data){
    return {
      id:uid(),
      type:data.type || "claim",
      title:data.title || "Untitled card",
      body:data.body || "",
      confidence:Number(data.confidence || 2),
      impact:Number(data.impact || 2),
      rung:data.rung || "raw"
    };
  }

  function addNode(parent, tag, className, text){
    var node = document.createElement(tag);
    if(className) node.className = className;
    if(text !== undefined) node.textContent = text;
    parent.appendChild(node);
    return node;
  }

  function render(){
    save();
    renderLadder();
    renderScore();
    renderWarnings();
    renderReceipt();
  }

  function renderLadder(){
    el.ladder.replaceChildren();

    rungs.forEach(function(rung){
      var section = addNode(el.ladder,"section","rung");
      section.setAttribute("data-rung",rung.id);

      var head = addNode(section,"div","runghead");
      var left = addNode(head,"div","rungtitle");
      addNode(left,"span","",rung.name);
      addNode(head,"span","badge",rung.note);

      var box = addNode(section,"div","cards");
      var inRung = cards.filter(function(card){ return card.rung === rung.id; });

      if(inRung.length === 0){
        addNode(box,"div","empty","No cards here yet.");
      }

      inRung.forEach(function(card){
        var item = addNode(box,"article","card" + (card.id === selectedId ? " selected" : ""));
        item.setAttribute("tabindex","0");

        item.addEventListener("click",function(){
          selectedId = card.id;
          render();
        });

        item.addEventListener("keydown",function(e){
          if(e.key === "Enter" || e.key === " "){
            e.preventDefault();
            selectedId = card.id;
            render();
          }
        });

        var top = addNode(item,"div","cardtop");
        addNode(top,"span","type " + card.type,typeLabel(card.type));

        var btns = addNode(top,"div","cardbuttons");

        var down = addNode(btns,"button","", "↓");
        down.setAttribute("aria-label","Move card down");
        down.addEventListener("click",function(e){
          e.stopPropagation();
          moveCard(card.id,-1);
        });

        var up = addNode(btns,"button","", "↑");
        up.setAttribute("aria-label","Move card up");
        up.addEventListener("click",function(e){
          e.stopPropagation();
          moveCard(card.id,1);
        });

        var edit = addNode(btns,"button","", "Edit");
        edit.addEventListener("click",function(e){
          e.stopPropagation();
          loadIntoEditor(card.id);
        });

        var del = addNode(btns,"button","", "×");
        del.setAttribute("aria-label","Delete card");
        del.addEventListener("click",function(e){
          e.stopPropagation();
          cards = cards.filter(function(c){ return c.id !== card.id; });
          if(selectedId === card.id) selectedId = null;
          render();
        });

        addNode(item,"div","cardtitle",card.title);
        addNode(item,"div","cardtext",card.body || "No note written.");

        var meta = addNode(item,"div","cardmeta");
        addNode(meta,"span","chip","Confidence " + card.confidence + "/3");
        addNode(meta,"span","chip","Impact " + card.impact + "/3");
        addNode(meta,"span","chip","Rung " + (rungIndex(card) + 1));
      });
    });
  }

  function moveCard(id,delta){
    var card = cards.find(function(c){ return c.id === id; });
    if(!card) return;
    var next = Math.max(0,Math.min(rungs.length - 1,rungIndex(card) + delta));
    card.rung = rungs[next].id;
    selectedId = id;
    render();
  }

  function loadIntoEditor(id){
    var card = cards.find(function(c){ return c.id === id; });
    if(!card) return;
    el.cardType.value = card.type;
    el.cardTitle.value = card.title;
    el.cardBody.value = card.body;
    el.confidence.value = String(card.confidence);
    el.impact.value = String(card.impact);
    selectedId = id;
    render();
  }

  function scoreData(){
    var total = cards.length;
    var foundation = cards.filter(function(c){ return c.rung === "first" || c.rung === "proof" || c.rung === "test" || c.rung === "held"; }).length;
    var proof = cards.filter(function(c){ return c.type === "evidence" && (c.rung === "proof" || c.rung === "test" || c.rung === "held"); }).length;
    var experiments = cards.filter(function(c){ return c.type === "experiment" && (c.rung === "test" || c.rung === "held"); }).length;
    var highClaims = cards.filter(function(c){ return c.type === "claim" && (c.rung === "test" || c.rung === "held"); }).length;
    var rawFatal = cards.filter(function(c){ return c.rung === "raw" && c.impact === 3; }).length;
    var unsupportedAssumptions = cards.filter(function(c){ return c.type === "assumption" && c.impact >= 2 && (c.rung === "raw" || c.rung === "first"); }).length;

    var points = 0;

    cards.forEach(function(c){
      var base = rungIndex(c) * 8;
      var conf = c.confidence * 3;
      var riskPenalty = c.impact === 3 && rungIndex(c) < 2 ? 10 : 0;
      points += base + conf - riskPenalty;
    });

    points += Math.min(18, proof * 6);
    points += Math.min(16, experiments * 8);
    points += Math.min(12, foundation * 2);

    if(total === 0) points = 0;
    if(highClaims > proof + experiments) points -= 18;
    if(rawFatal > 0) points -= rawFatal * 14;
    if(unsupportedAssumptions > 0) points -= unsupportedAssumptions * 8;

    var max = Math.max(60,total * 36);
    var score = Math.round(Math.max(0,Math.min(100,(points / max) * 100)));

    return {
      total:total,
      foundation:foundation,
      proof:proof,
      experiments:experiments,
      highClaims:highClaims,
      rawFatal:rawFatal,
      unsupportedAssumptions:unsupportedAssumptions,
      score:score
    };
  }

  function renderScore(){
    var s = scoreData();
    el.scoreText.textContent = String(s.score);
    el.scoreFill.style.width = String(s.score) + "%";
    el.foundationCount.textContent = String(s.foundation);
    el.proofCount.textContent = String(s.proof);
    el.experimentCount.textContent = String(s.experiments);

    if(s.total === 0){
      el.verdict.textContent = "Unbuilt";
      el.verdict.className = "verdict";
      el.scoreNote.textContent = "Add or test cards to score the plan.";
      return;
    }

    if(s.score >= 75 && s.rawFatal === 0 && s.unsupportedAssumptions <= 1){
      el.verdict.textContent = "Holds";
      el.verdict.className = "verdict hold";
      el.scoreNote.textContent = "The plan has a usable foundation, proof, and test path.";
    }else if(s.score >= 45){
      el.verdict.textContent = "Shaky";
      el.verdict.className = "verdict shaky";
      el.scoreNote.textContent = "The plan might work, but weak assumptions still carry real risk.";
    }else{
      el.verdict.textContent = "Collapses";
      el.verdict.className = "verdict collapse";
      el.scoreNote.textContent = "The plan is leaning on untested or unsupported cards.";
    }
  }

  function getWarnings(){
    var s = scoreData();
    var notes = [];

    if(cards.length === 0){
      notes.push({kind:"warn", text:"No cards yet. Start by writing the main claim and the scariest assumption."});
      return notes;
    }

    if(cards.filter(function(c){ return c.type === "claim"; }).length === 0){
      notes.push({kind:"bad", text:"No claim card. The ladder needs one central statement that can be proven or killed."});
    }

    if(cards.filter(function(c){ return c.type === "assumption"; }).length === 0){
      notes.push({kind:"bad", text:"No assumption cards. Hidden assumptions are where fragile plans usually break."});
    }

    if(s.proof === 0){
      notes.push({kind:"bad", text:"No evidence has reached the evidence rung. The plan is still mostly opinion."});
    }

    if(s.experiments === 0){
      notes.push({kind:"warn", text:"No experiment has reached the test rung. Add a cheap falsification test before committing hard."});
    }

    if(s.rawFatal > 0){
      notes.push({kind:"bad", text:"A fatal-impact card is still a raw hunch. Move it down into a test, or treat the plan as collapsed."});
    }

    if(s.unsupportedAssumptions > 0){
      notes.push({kind:"bad", text:String(s.unsupportedAssumptions) + " material or fatal assumption card(s) remain weakly supported."});
    }

    if(s.highClaims > s.proof + s.experiments){
      notes.push({kind:"warn", text:"Top-rung claims outnumber proof and experiments. The conclusion is climbing faster than the support."});
    }

    if(notes.length === 0){
      notes.push({kind:"warn", text:"No major collapse flags. Keep the strongest experiment current and watch for stale proof."});
    }

    return notes;
  }

  function renderWarnings(){
    el.warnings.replaceChildren();
    getWarnings().forEach(function(note){
      addNode(el.warnings,"div","warnitem " + (note.kind === "bad" ? "bad" : ""),note.text);
    });
  }

  function receiptText(){
    var s = scoreData();
    var verdict = el.verdict.textContent;
    var lines = [];

    lines.push("FIRST-PRINCIPLES CLAIM LADDER RECEIPT");
    lines.push("Plan: " + (el.planName.value.trim() || "Untitled plan"));
    lines.push("Score: " + s.score + "/100");
    lines.push("Verdict: " + verdict);
    lines.push("");
    lines.push("Counts");
    lines.push("- Cards: " + s.total);
    lines.push("- Foundation cards: " + s.foundation);
    lines.push("- Evidence cards at proof or higher: " + s.proof);
    lines.push("- Experiment cards at test or higher: " + s.experiments);
    lines.push("");

    lines.push("Collapse checks");
    getWarnings().forEach(function(note){
      lines.push("- " + note.text);
    });

    lines.push("");
    lines.push("Ladder");
    rungs.forEach(function(rung){
      lines.push(rung.name);
      var inRung = cards.filter(function(c){ return c.rung === rung.id; });
      if(inRung.length === 0){
        lines.push("- Empty");
      }else{
        inRung.forEach(function(c){
          lines.push("- [" + typeLabel(c.type) + "] " + c.title);
          lines.push("  Confidence: " + c.confidence + "/3 | Impact if wrong: " + c.impact + "/3");
          if(c.body.trim()){
            lines.push("  Note: " + c.body.trim().replace(/\s+/g," "));
          }
        });
      }
      lines.push("");
    });

    lines.push("Next reasoning move");
    if(s.score >= 75){
      lines.push("Keep the plan, but rerun the ladder after the next real-world result.");
    }else if(s.score >= 45){
      lines.push("Do not scale yet. Promote one evidence card and one experiment card before committing more resources.");
    }else{
      lines.push("Treat the plan as collapsed until the fatal assumptions are tested or replaced.");
    }

    return lines.join("\n");
  }

  function renderReceipt(){
    el.receipt.textContent = receiptText();
  }

  function save(){
    var payload = {
      planName:el.planName.value,
      cards:cards
    };
    try{
      localStorage.setItem("firstPrinciplesClaimLadder",JSON.stringify(payload));
    }catch(e){}
  }

  function load(){
    try{
      var raw = localStorage.getItem("firstPrinciplesClaimLadder");
      if(!raw) return false;
      var payload = JSON.parse(raw);
      if(payload && Array.isArray(payload.cards)){
        cards = payload.cards;
        el.planName.value = payload.planName || el.planName.value;
        return true;
      }
    }catch(e){}
    return false;
  }

  function addFromEditor(){
    var title = el.cardTitle.value.trim();
    var body = el.cardBody.value.trim();

    if(!title){
      title = typeLabel(el.cardType.value) + " card";
    }

    if(selectedId){
      var existing = cards.find(function(c){ return c.id === selectedId; });
      if(existing){
        existing.type = el.cardType.value;
        existing.title = title;
        existing.body = body;
        existing.confidence = Number(el.confidence.value);
        existing.impact = Number(el.impact.value);
        render();
        clearEditor(false);
        return;
      }
    }

    cards.push(makeCard({
      type:el.cardType.value,
      title:title,
      body:body,
      confidence:Number(el.confidence.value),
      impact:Number(el.impact.value),
      rung:"raw"
    }));
    selectedId = null;
    clearEditor(false);
    render();
  }

  function clearEditor(clearSelection){
    el.cardTitle.value = "";
    el.cardBody.value = "";
    el.confidence.value = "2";
    el.impact.value = "2";
    if(clearSelection) selectedId = null;
  }

  function loadSample(){
    el.planName.value = "Launch a paid prompt-library vault";
    cards = [
      makeCard({
        type:"claim",
        title:"Builders will pay for reusable finished paths",
        body:"The core claim is that people want the completed workflow, not just isolated prompts.",
        confidence:2,
        impact:3,
        rung:"first"
      }),
      makeCard({
        type:"assumption",
        title:"The pain is repetition, not discovery",
        body:"Users already know what they want to build, but they stall when each project starts from zero.",
        confidence:2,
        impact:3,
        rung:"first"
      }),
      makeCard({
        type:"evidence",
        title:"Repeated requests cluster around offline tools",
        body:"Past build requests show recurring patterns: one-file tools, receipts, safety checks, and export workflows.",
        confidence:3,
        impact:2,
        rung:"proof"
      }),
      makeCard({
        type:"experiment",
        title:"Ship five public paths and measure forks",
        body:"Publish five complete paths, track saves, forks, and repeat visits before building paid access.",
        confidence:2,
        impact:2,
        rung:"test"
      }),
      makeCard({
        type:"assumption",
        title:"Trust increases when proof is visible",
        body:"A path with prompts, outputs, revisions, and artifacts should feel safer than a raw prompt.",
        confidence:2,
        impact:2,
        rung:"proof"
      }),
      makeCard({
        type:"claim",
        title:"The plan can start free before monetization",
        body:"Free usage can validate demand before pricing is introduced.",
        confidence:2,
        impact:2,
        rung:"held"
      })
    ];
    selectedId = null;
    render();
  }

  async function copyReceipt(){
    var text = receiptText();
    el.copyStatus.textContent = "";

    if(navigator.clipboard && navigator.clipboard.writeText){
      try{
        await navigator.clipboard.writeText(text);
        el.copyStatus.textContent = "Copied receipt.";
        return;
      }catch(e){
        el.copyStatus.textContent = "Clipboard blocked. Select the receipt text and copy it manually.";
        el.receipt.focus();
        return;
      }
    }

    el.copyStatus.textContent = "Clipboard unavailable. Select the receipt text and copy it manually.";
    el.receipt.focus();
  }

  function downloadReceipt(){
    var blob = new Blob([receiptText()],{type:"text/plain;charset=utf-8"});
    var url = URL.createObjectURL(blob);
    var a = document.createElement("a");
    a.href = url;
    a.download = "first-principles-claim-ladder-receipt.txt";
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
    el.copyStatus.textContent = "Downloaded receipt.";
  }

  el.addCard.addEventListener("click",addFromEditor);
  el.loadSample.addEventListener("click",loadSample);

  el.resetBoard.addEventListener("click",function(){
    cards = [];
    selectedId = null;
    clearEditor(true);
    try{ localStorage.removeItem("firstPrinciplesClaimLadder"); }catch(e){}
    render();
  });

  el.copyReceipt.addEventListener("click",copyReceipt);
  el.downloadReceipt.addEventListener("click",downloadReceipt);

  el.planName.addEventListener("input",renderReceipt);

  [el.cardType,el.confidence,el.impact].forEach(function(node){
    node.addEventListener("change",function(){
      el.copyStatus.textContent = "";
    });
  });

  [el.cardTitle,el.cardBody].forEach(function(node){
    node.addEventListener("input",function(){
      el.copyStatus.textContent = "";
    });
  });

  if(!load()){
    loadSample();
  }else{
    render();
  }
})();
</script>
</body>
</html>
